df = pd.read_csv(StringIO(DATA.strip()))

# Columns you asked for
basic_col = "total_basic_reward"
added_col = "total_added_reward"
collision_col = "collision"

# Compute mean + std (sample std, ddof=1)
basic_mean = df[basic_col].mean()
basic_std  = df[basic_col].std(ddof=1)

added_mean = df[added_col].mean()
added_std  = df[added_col].std(ddof=1)

# % episodes with collisions (treat any nonzero as collision)
collision_rate = (df[collision_col].astype(float) != 0).mean() * 100.0

print(f"{basic_col}: mean={basic_mean:.6f}, std={basic_std:.6f}")
print(f"{added_col}: mean={added_mean:.6f}, std={added_std:.6f}")
print(f"collision rate: {collision_rate:.2f}% ({int((df[collision_col].astype(float)!=0).sum())}/{len(df)})")
